-- Replaces all placeholder reviews with the customer-approved dataset exported on 2026-07-30.
-- Hex encoding preserves JSON escapes and Unicode independently of SQL string escape modes.
DELETE FROM reviews;

SET @customer_reviews_json = CONVERT( USING utf8mb4);

INSERT INTO reviews (site_id, author_name, context_label, rating, review_text, sort_order, is_active)
SELECT site.id, source.author_name, source.context_label, source.rating,
       source.review_text, source.sort_order, source.is_active
FROM sites AS site
CROSS JOIN JSON_TABLE(
    @customer_reviews_json,
    '$[*]' COLUMNS (
        author_name VARCHAR(190) PATH '$.author_name',
        context_label VARCHAR(190) PATH '$.context_label',
        rating TINYINT PATH '$.rating',
        review_text TEXT PATH '$.review_text',
        sort_order INT PATH '$.sort_order',
        is_active TINYINT PATH '$.is_active'
    )
) AS source;

SET @customer_reviews_json = NULL;
